115	export function setupExplore(ctrl: SwingController): void {
116	  exNightBind(ctrl);
117	  window.addEventListener('keydown', (e) => {
118	    if (!inGlider()) return;
119	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
120	    if (watching) return;   // xem: không lái, không ghi phím
