1	import { CONFIG } from '../config';
2	import { camera, controls, canvas, renderer } from '../core/renderer';
3	import { clamp, smooth } from '../common/math';
4	import { deckY } from '../bridges/dragon/profile';
5	import { tpRoadY } from '../bridges/thuan-phuoc/profile';
6	import { hrRoadY } from '../bridges/han-tunnel/profile';
7	import { VIEWS, type ViewPreset } from './presets';
8	import { narration } from '../audio/narration';
9	import { cam, keys } from './state';
10	import { getWeather } from '../environment/weather';
11	import { swRide } from '../bridges/sun-wheel/ride';
12	import { TOUR_VIEWS, activeTour, setActiveTour, tour, tourBox, showTourCaption, startTour, updateTour } from './tour';
13	
14	/* ============================ Góc nhìn & điều khiển camera ============================ */
15	const drive = { x: -700 };
16	const tpDrive = { x: -1300 };
17	export const hrDrive = { x: -1000 };
18	const walk = { x: -240, z: 17.4, yaw: 0 };
19	/* Mắt thích nghi khi lái vào/ra hầm: độ phơi sáng nhân hệ số k, về 0,7 trong hầm (τ ≈ 0,5 s ⇒ ổn định sau ~1,5 s) rồi trả về 1 */
20	const eye = { k: 1 };
21	
22	/* Ngồi cabin Vòng quay Mặt Trời (cam.mode = 'swRide'): tư thế camera do SunWheel.update đặt (ride.ts). Mọi đường rời chế độ (flyTo, setView, kịch bản bão) đi qua dropRide() */
23	const rideHint = () => document.getElementById('swRideHint');
24	function dropRide() {
25	  if (cam.mode !== 'swRide') return;
26	  cam.mode = 'orbit'; controls.enabled = true;
27	  document.querySelectorAll('[data-view]').forEach((b) => b.setAttribute('aria-pressed', 'false'));
28	  rideHint().hidden = true;
29	}
30	export function enterSwRide() {
31	  if (cam.mode === 'swRide' || !swRide.wheel) return;
32	  swRide.begin();
33	  cam.flight.then = null; cam.mode = 'swRide'; controls.enabled = false;
34	  document.querySelectorAll<HTMLElement>('[data-view]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.view === 'swRide')));
35	  rideHint().hidden = false;
36	}
37	/* Xuống cabin: restore = true thì bay về chỗ đã đứng trước khi lên và trả OrbitControls như cũ (Esc, bấm lại nút); false thì giữ nguyên chỗ (đã có chuyến bay khác nối tiếp) */
38	export function leaveSwRide(restore = true) {
39	  if (cam.mode !== 'swRide') return;
40	  const s = swRide.saved;
41	  if (restore) flyTo({ pos: s.pos.toArray() as [number, number, number], target: s.target.toArray() as [number, number, number], maxPolar: s.maxPolar });
42	  else dropRide();
43	}
44	
45	/* Bay mượt tới một góc nhìn; then = 'tour' để bắt đầu Tour khi tới nơi */
46	export function flyTo(v: ViewPreset, then: 'tour' | null = null) {
47	  dropRide();
48	  const flight = cam.flight;
49	  flight.then = then;
50	  controls.maxPolarAngle = v.maxPolar || Math.PI * 0.495;
51	  flight.fromP.copy(camera.position); flight.fromT.copy(controls.target);
52	  flight.toP.set(...v.pos); flight.toT.set(...v.target); flight.t = 0; cam.mode = 'fly'; controls.enabled = false;
53	}
54	export function setView(name: string) {
55	  narration.stop();
56	  if (name === 'swRide' && cam.mode === 'swRide') { leaveSwRide(true); return; }   // bấm lại nút Ngồi cabin = xuống
57	  dropRide();
58	  document.querySelectorAll<HTMLElement>('[data-view]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.view === name)));
59	  document.getElementById('hint').hidden = name !== 'walk';
60	  const tourKey = TOUR_VIEWS[name];
61	  tourBox().hidden = !tourKey; document.body.classList.toggle('touring', !!tourKey);
62	  if (tourKey) { setActiveTour(tourKey); showTourCaption(0); tour.shown = 0; flyTo(activeTour.stops[0], 'tour'); return; }
63	  if (name === 'drive') { cam.mode = 'drive'; controls.enabled = false; drive.x = -700; return; }
64	  if (name === 'tpDrive') { cam.mode = 'tpDrive'; controls.enabled = false; tpDrive.x = -1300; return; }
65	  if (name === 'hrDrive') { cam.mode = 'hrDrive'; controls.enabled = false; hrDrive.x = -1000; eye.k = 1; return; }
66	  if (name === 'swRide') { enterSwRide(); return; }
67	  if (name === 'walk') { cam.mode = 'walk'; controls.enabled = false; walk.x = -240; walk.z = 17.4; walk.yaw = 0; canvas.focus(); return; }
68	  flyTo(VIEWS[name]);
69	}
70	/* Kịch bản bão nắm camera (chế độ 'storm'): bỏ chọn nút góc nhìn, tắt Tour / lái xe / đi bộ; updateCamera() đọc scenario.pose() mỗi khung */
71	export function followScenario() {
72	  dropRide();
73	  document.querySelectorAll('[data-view]').forEach((b) => b.setAttribute('aria-pressed', 'false'));
74	  document.getElementById('hint').hidden = true;
75	  tourBox().hidden = true; document.body.classList.remove('touring');
76	  controls.maxPolarAngle = Math.PI * 0.495;
77	  cam.flight.then = null; cam.mode = 'storm'; controls.enabled = false;
78	}
79	export function updateCamera(dt: number) {
80	  const flight = cam.flight;
81	  if (cam.mode !== 'hrDrive') eye.k = 1;
82	  if (cam.mode === 'fly') {
83	    flight.t += dt / flight.dur; const k = smooth(Math.min(flight.t, 1));
84	    camera.position.lerpVectors(flight.fromP, flight.toP, k); controls.target.lerpVectors(flight.fromT, flight.toT, k);
85	    camera.lookAt(controls.target);
86	    if (flight.t >= 1) { if (flight.then === 'tour') startTour(); else { cam.mode = 'orbit'; controls.enabled = true; } }
87	  } else if (cam.mode === 'tour') {
88	    updateTour(dt);
89	  } else if (cam.mode === 'swRide') {
90	    /* tư thế do SunWheel.update đặt (sau khi vòng quay quay, cùng khung hình); không gọi controls.update() */
91	  } else if (cam.mode === 'glider') {
92	    /* tư thế do explore.update đặt ngay sau updateCamera; không gọi controls.update() */
93	  } else if (cam.mode === 'storm') {
94	    const sc = getWeather()?.scenario;
95	    if (sc?.running && sc.cameraOwned) { sc.pose(sc.t, camera.position, controls.target); camera.lookAt(controls.target); }
