115	export function setupExplore(ctrl: SwingController): void {
116	  exNightBind(ctrl);
117	  window.addEventListener('keydown', (e) => {
118	    if (!inGlider()) return;
119	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
120	    if (watching) return;   // xem: không lái, không ghi phím
121	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
122	    const t = e.target as HTMLElement | null;
123	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
124	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
125	    const k = e.key.toLowerCase(); keys.add(k);
126	    if (k.startsWith('arrow')) e.preventDefault();
127	  });
128	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
129	  for (const id of ['langSelect', 'qualitySel']) {
130	    const sel = document.getElementById(id); if (!sel) continue;
131	    let byMouse = false;
132	    sel.addEventListener('pointerdown', () => { byMouse = true; });
133	    sel.addEventListener('keydown', () => { byMouse = false; });
134	    sel.addEventListener('change', () => { if (byMouse && active()) sel.blur(); byMouse = false; });
135	  }
136	  const q = new URLSearchParams(location.search);
137	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
138	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
139	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
140	  if (q.get('explore') === 'glider') { explore.start(); return; }
141	  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); }, () => explore.startWatching());   // 'guided': màn chọn tự ẩn, giao diện cũ
142	}
