1	import * as THREE from 'three';
2	import { scene } from '../../core/renderer';
3	import { CONFIG } from '../../config';
4	import { buildAtlas, type Atlas } from './adAtlas';
5	import { clearRects, collectBuildings, snapshot, type Rect } from './clearance';
6	import { buildLandmarks, type Landmarks } from './landmarks';
7	import { buildHearts, type Hearts } from './heartFacade';
8	import { buildBillboards, panoRects, type Billboards } from './billboards';
9	import { buildPromenade, type Promenade } from './promenade';
10	
11	/* [riverfront] Hai bờ sông Hàn: địa danh thật, mặt dựng LED trái tim + "DN", bảng quảng cáo, chi tiết bờ.
12	   Gọi buildRiverfront() SAU mọi lệnh dựng có dùng rand() (sau HanTunnel trong main.ts): chỉ thu nhỏ instance nhà/cây bị đè về 0. */
13	export interface Riverfront {
14	  group: THREE.Group; atlas: Atlas; landmarks: Landmarks; hearts: Hearts; billboards: Billboards; promenade: Promenade;
15	  footprints: Rect[]; cleared: { buildings: number; plants: number }; snapshot: typeof snapshot;
16	  adsEnabled: boolean;
17	}
18	let current: Riverfront | null = null;
19	export const getRiverfront = () => current;
20	
21	export function buildRiverfront(): Riverfront {
22	  const group = new THREE.Group(); group.name = 'riverfront';
23	  const atlas = buildAtlas(), landmarks = buildLandmarks();
24	  const footprints = [...landmarks.rects, ...panoRects()];
25	  const cleared = clearRects(footprints, CONFIG.riverfront.clearMargin);
26	  const buildings = collectBuildings();                    // nhà còn lại sau khi dọn: chọn mái, mặt tiền, cửa hàng từ đây
27	  const hearts = buildHearts(landmarks.towers);
28	  const billboards = buildBillboards(atlas, landmarks, buildings);
29	  const promenade = buildPromenade(atlas, billboards.adMat, buildings);
30	  group.add(landmarks.mesh, hearts.mesh, billboards.group, promenade.group);
31	  scene.add(group);
32	  current = { group, atlas, landmarks, hearts, billboards, promenade, footprints, cleared, snapshot, adsEnabled: true };
33	  return current;
34	}
35	export function updateRiverfront(dt: number, _time: number) {
36	  if (!current) return;
37	  current.hearts.update(dt);
38	  if (current.adsEnabled) { current.billboards.update(dt); current.promenade.update(); }
39	}
40	export function setHeartsEnabled(on: boolean) { current?.hearts.setEnabled(on); }
41	export function setHeartsMode(m: 'duet' | 'sync') { current?.hearts.setMode(m); }
42	/* "Quảng cáo": bảng quảng cáo + băng rôn + bảng hiệu; không tắt chi tiết bờ (lan can, ghế…) */
43	export function setAdsEnabled(on: boolean) { if (!current) return; adsWanted = on; applyAds(); }
44	/* Thời tiết (bão) tắt quảng cáo tạm thời; hết bão trả đúng lựa chọn của người dùng (adsWanted), không ép bật */
45	export function setAdsSuppressed(on: boolean) { adsSuppressed = on; applyAds(); }
46	let adsWanted = true, adsSuppressed = false;
47	function applyAds() { if (!current) return; const on = adsWanted && !adsSuppressed; if (current.adsEnabled === on) return; current.adsEnabled = on; current.billboards.setEnabled(on); }
48	export function disposeRiverfront() {
49	  if (!current) return;
50	  const c = current; c.hearts.dispose(); c.billboards.dispose(); c.promenade.dispose(); c.atlas.dispose();
51	  c.landmarks.mesh.geometry.dispose(); (c.landmarks.mesh.material as THREE.Material).dispose(); c.group.removeFromParent(); current = null;
52	}
